def _interface(g):
    for key in ('Cycle','Pavement'):g.socket(key,'NodeSocketGeometry')
    for key,value in (('Join Radius',.5),('Cell Size',.4),('Chord Error',.005)):g.socket(key,'NodeSocketFloat',default=value)
    for key,value in (('Padding',2),('Pavement Rows',10),('Core Rows',8)):g.socket(key,'NodeSocketInt',default=value)
    for key in ('Geometry','Status','Boundary','Outer','Removed','Replacement'):g.socket(key,'NodeSocketGeometry','OUTPUT')
    g.socket('Valid','NodeSocketBool','OUTPUT')


