def build():
    """Accept the first valid flat disk, growing only its private interface.

    Finer pavement sampling can produce a staircase rim that cannot support
    positive straight quad rows. Retry with successive existing face layers,
    never beyond the region primitive's original padding budget of eight.
    All source profiles, rounded separator samples and validity guards remain
    fixed. An already accepted candidate passes through exactly. If no bounded
    candidate works, preserve the original pavement and report rejection.
    """
    if NAME in bpy.data.node_groups:return bpy.data.node_groups[NAME]
    g=c.Graph(NAME);_interface(g)
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    outputs=('Geometry','Status','Boundary','Outer','Removed','Replacement')
    first=g.node('GeometryNodeGroup','Original candidate; valid inputs bypass all retries')
    first.node_tree=_attempt()
    for key in ('Cycle','Pavement','Join Radius','Cell Size','Chord Error','Padding','Pavement Rows','Core Rows'):
        g.bind(inp.outputs[key],first.inputs[key])
    start=g.node('GeometryNodeRepeatInput','Bounded enclosing-disk candidates')
    end=g.node('GeometryNodeRepeatOutput','Keep the first accepted native partition')
    end.repeat_items.clear()
    for key in outputs:end.repeat_items.new('GEOMETRY',key)
    end.repeat_items.new('BOOLEAN','Valid');start.pair_with_output(end)
    padding=c.V(g,inp.outputs['Padding'])
    within=g.math('GREATER_THAN',padding,-.5)*g.math('LESS_THAN',padding,8.5)
    # The primary candidate emits the normal false status for out-of-budget
    # requests. Only rejected in-budget inputs allocate a retry zone.
    g.bind(c.choose(g,within,8.-padding,0,'INT'),start.inputs['Iterations'])
    for key in outputs:g.bind(first.outputs[key],start.inputs[key])
    attempt=g.node('GeometryNodeGroup','Same construction and guards for each candidate')
    attempt.node_tree=_attempt()
    for key in ('Cycle','Pavement','Join Radius','Cell Size','Chord Error','Pavement Rows','Core Rows'):
        g.bind(inp.outputs[key],attempt.inputs[key])
    g.bind(padding+1.+c.V(g,start.outputs['Iteration']),attempt.inputs['Padding'])
    for key in outputs:
        g.bind(c.choose(g,start.outputs['Valid'],start.outputs[key],attempt.outputs[key],'GEOMETRY'),end.inputs[key])
        g.bind(c.choose(g,first.outputs['Valid'],first.outputs[key],end.outputs[key],'GEOMETRY'),out.inputs[key])
    g.bind(c.choose(g,start.outputs['Valid'],True,attempt.outputs['Valid'],'BOOLEAN'),end.inputs['Valid'])
